import {loadDialogueCatalog,resolveDialogue} from './dialogue-data.js';
import {dialogueDiagnostics} from './dialogue-schema.js';
import {FACTIONS,ATTITUDES,COMBAT_BEHAVIORS,RESOURCE_TYPES,characters,characterName,knownCharacterReferences} from './character-properties.js';
import {SPECIES,WEAPON_IDS} from './core/maps.js';
export function installCharacterProperties({getDocument,getSelection,run,status}){
 const host=document.createElement('section');host.id='character-properties';host.hidden=true;
 host.innerHTML=`<h2>Character properties</h2><p class="muted">Appearance and display names work in playtest. Faction, attitude and combat behavior work in playtest. Player-faction characters start non-hostile; attacking a character makes it hostile. Cower and flee never fire back. Right-click a talk-capable character in playtest to converse. Trading awaits gameplay integration.</p><label>Display name<input id="char-name" maxlength="100"></label><label>Species<select id="char-species"></select></label><label>Model<select id="char-model"></select></label><label>Outfit<select id="char-outfit"></select></label><label>Visual variant<select id="char-variant"><option value="default">Default</option></select></label><label>Held equipment<select id="char-weapon"></select></label><label>Climbing skill<input id="char-climbing" type="number" min="1" max="100" step="1" value="50"></label><label>Faction<select id="char-faction"></select></label><label>Starting attitude<select id="char-attitude"></select></label><label>Combat behavior<select id="char-combat"></select></label><details id="char-extra"><summary>Dialogue, shop & scripting</summary><label class="check"><input id="char-talk" type="checkbox">Can talk</label><div id="char-dialogue-settings"><label>Dialogue reference<input id="char-dialogue" maxlength="80" list="char-dialogue-list"></label><datalist id="char-dialogue-list"></datalist><details><summary>Author dialogue JSON</summary><p class="muted">One resource can serve several characters. Import JSON or load the current reference, edit the lines, then save. Use a new ID for a new conversation. Saving an existing ID replaces it for all characters in this map; existing game saves keep their pinned version.</p><button type="button" id="char-dialogue-load">Load referenced dialogue</button><label>Import dialogue JSON<input type="file" id="char-dialogue-file" accept=".json,application/json"></label><label>Dialogue definition<textarea id="char-dialogue-json" rows="12" spellcheck="false"></textarea></label><button type="button" id="char-dialogue-save">Save / replace this dialogue</button><p id="char-dialogue-status" role="status"></p></details></div><label class="check"><input id="char-sell" type="checkbox">Can sell</label><div id="char-shop-settings"><label>Shop inventory reference<input id="char-inventory" maxlength="80" list="char-inventory-list"></label><datalist id="char-inventory-list"></datalist><label>Pricing reference<input id="char-pricing" maxlength="80" list="char-pricing-list"></label><datalist id="char-pricing-list"></datalist></div><label>Stable name / Script ID<input id="char-script" maxlength="80"></label><p class="muted">A unique name used to identify this character in dialogue, quests, and scripts—for example, <code>town_shopkeeper</code>. Renaming may affect external scripts.</p><p id="char-rename-note" role="status"></p><h3>Known references to this character</h3><ul id="char-incoming"></ul><h3>Character connections</h3><p class="muted">Connections store permanent identities and show readable names. Example roles: quest_target, shop_partner.</p><div id="char-links"></div><button id="char-add-link" type="button">Add character connection</button></details><button id="char-apply">Apply character changes</button><details><summary>Duplicate character</summary><div class="row"><label>Tile X<input id="char-copy-x" type="number" min="0" max="239"></label><label>Tile Y<input id="char-copy-y" type="number" min="0" max="239"></label><label>Floor<input id="char-copy-z" type="number" min="1" max="3"></label></div><button id="char-copy">Duplicate to tile</button></details><details><summary>Available dialogue & shop resources</summary><p class="muted">Register known resource IDs, one per line. These declare external resources; they do not create dialogue, inventory or pricing content.</p><label>Dialogue IDs<textarea id="char-res-dialogues"></textarea></label><label>Shop inventory IDs<textarea id="char-res-shopInventories"></textarea></label><label>Pricing IDs<textarea id="char-res-shopPricing"></textarea></label><button id="char-res-apply">Save resource catalog</button></details><p id="char-warnings" role="status"></p>`;
 document.querySelector('.properties').append(host);const $=id=>host.querySelector('#'+id);
 for(const [id,items]of [['char-species',SPECIES],['char-weapon',WEAPON_IDS],['char-faction',FACTIONS],['char-attitude',ATTITUDES],['char-combat',COMBAT_BEHAVIORS]])for(const value of items)$(id).add(new Option(value==='red-hats'?'Red Hats':value.charAt(0).toUpperCase()+value.slice(1),value));
 let selectedId=null,oldScript='';
 function appearance(){const species=$('char-species').value,previous=$('char-outfit').value;$('char-model').replaceChildren(new Option(species+' · existing 3D model',species+'-10k'));$('char-outfit').replaceChildren(new Option('Original','normal'),new Option('Red Hats','red-hats'));if(species==='donkey')$('char-outfit').add(new Option('Town guide · Hawaiian shirt & straw hat','blue-hawaiian'));$('char-outfit').value=[...$('char-outfit').options].some(o=>o.value===previous)?previous:'normal';}
 function capabilities(){$('char-dialogue-settings').hidden=!$('char-talk').checked;$('char-shop-settings').hidden=!$('char-sell').checked;}
 function linkRow(ref={role:'related_character',targetId:''}){const row=document.createElement('div');row.className='row';const role=document.createElement('input');role.value=ref.role;role.maxLength=80;role.setAttribute('aria-label','Connection role');const target=document.createElement('select');target.setAttribute('aria-label','Connected character');target.add(new Option('Choose character',''));for(const {p,index,field}of characters(getDocument().map))target.add(new Option(characterName(p,(field==='starts'?'Squad ':'Character ')+(index+1))+(p.character.scriptId?' · '+p.character.scriptId:'')+` (${p.x}, ${p.y})`,p.character.id));if(ref.targetId&&![...target.options].some(o=>o.value===ref.targetId))target.add(new Option('Missing character (unresolved link)',ref.targetId));target.value=ref.targetId;const remove=document.createElement('button');remove.type='button';remove.textContent='Remove';remove.onclick=()=>row.remove();row.append(role,target,remove);$('char-links').append(row);}
 $('char-species').onchange=appearance;$('char-talk').onchange=$('char-sell').onchange=capabilities;$('char-add-link').onclick=()=>linkRow();
 $('char-script').oninput=()=>{$('char-rename-note').textContent=$('char-script').value.trim()!==oldScript?'Editor-managed connections keep their internal targets. External scripts using the old Script ID may need updating.':'';};
 $('char-apply').onclick=()=>{if(!selectedId)return;const id=selectedId;const patch={stats:{...getDocument().character(id).p.stats,climbing:Number($('char-climbing').value)},species:$('char-species').value,outfit:$('char-outfit').value,weapon:$('char-weapon').value,character:{displayName:$('char-name').value.trim(),scriptId:$('char-script').value.trim(),model:$('char-model').value,visualVariant:$('char-variant').value,faction:$('char-faction').value,attitude:$('char-attitude').value,combatBehavior:$('char-combat').value,canTalk:$('char-talk').checked,canSell:$('char-sell').checked,dialogueRef:$('char-dialogue').value.trim(),shopInventoryRef:$('char-inventory').value.trim(),shopPricingRef:$('char-pricing').value.trim(),references:[...$('char-links').children].map(row=>({role:row.querySelector('input').value.trim(),targetId:row.querySelector('select').value}))}};run(()=>getDocument().updateCharacter(id,patch),'Character updated. Existing connections preserved.');};
 $('char-copy').onclick=()=>{if(!selectedId)return;const id=selectedId,point={x:+$('char-copy-x').value,y:+$('char-copy-y').value,z:+$('char-copy-z').value-1};run(()=>getDocument().duplicateCharacter(id,point),'Character duplicated with a new identity.');};
 $('char-res-apply').onclick=()=>run(()=>getDocument().characterResources(Object.fromEntries(RESOURCE_TYPES.map(type=>[type,$('char-res-'+type).value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)]))),'Resource catalog saved.');
 function sync(){const d=getDocument(),selection=getSelection();if(d)d.dialogueCatalog=catalog;selectedId=selection?.type==='unit'?selection.data.character?.id:null;const row=selectedId&&d?.character(selectedId);host.hidden=!row;if(!row)return;const {p,field,index}=row,c=p.character;oldScript=c.scriptId;$('char-climbing').value=p.stats?.climbing??50;$('char-name').value=c.displayName;$('char-script').value=c.scriptId;$('char-species').value=p.species||['horse','goat','donkey','sheep'][index]||'horse';appearance();$('char-outfit').value=p.outfit||'normal';$('char-weapon').value=p.weapon||(field==='starts'?['assault','rifle','pistol','knife'][index]:'pistol');$('char-faction').value=c.faction;$('char-attitude').value=c.attitude;$('char-combat').value=c.combatBehavior||(c.category==='npc'?'cower':'fight');$('char-talk').checked=c.canTalk;$('char-sell').checked=c.canSell;$('char-dialogue').value=c.dialogueRef;$('char-inventory').value=c.shopInventoryRef;$('char-pricing').value=c.shopPricingRef;capabilities();$('char-rename-note').textContent='';$('char-links').replaceChildren();for(const link of c.references)linkRow(link);$('char-incoming').replaceChildren();for(const ref of knownCharacterReferences(d.editor.map,c.id)){const li=document.createElement('li');li.textContent=ref.name+' · '+ref.role;$('char-incoming').append(li);}if(!$('char-incoming').children.length){const li=document.createElement('li');li.textContent='No known editor-managed references.';$('char-incoming').append(li);}$('char-copy-x').value=Math.min(d.size-1,p.x+1);$('char-copy-y').value=p.y;$('char-copy-z').value=(p.z||0)+1;$('char-copy').disabled=field==='starts';for(const type of RESOURCE_TYPES)$('char-res-'+type).value=(d.editor.map.characterResources?.[type]||[]).join('\n');for(const [id,type]of [['dialogue','dialogues'],['inventory','shopInventories'],['pricing','shopPricing']])$('char-'+id+'-list').replaceChildren(...[...new Set([...(d.editor.map.characterResources?.[type]||[]),...(type==='dialogues'?Object.keys(catalog.definitions):[])])].map(value=>new Option(value,value)));$('char-warnings').textContent=d.characterWarnings().join('\n');}
 let catalog={definitions:{},errors:{}};
 loadDialogueCatalog().then(result=>{catalog=result;sync();}).catch(e=>{$('char-dialogue-status').textContent=e.message;});
 $('char-dialogue-load').onclick=()=>{try{const d=resolveDialogue(getDocument().editor.map,null,$('char-dialogue').value.trim(),catalog);$('char-dialogue-json').value=JSON.stringify(d,null,2);$('char-dialogue-status').textContent='Version '+d.version+' · '+Object.keys(d.nodes).length+' nodes.';}catch(e){$('char-dialogue-status').textContent=e.message;}};
 $('char-dialogue-file').onchange=async()=>{const file=$('char-dialogue-file').files[0];if(!file)return;if(file.size>262144){$('char-dialogue-status').textContent='Dialogue exceeds 256 KiB.';return;}$('char-dialogue-json').value=await file.text();};
 $('char-dialogue-save').onclick=async()=>{try{const definition=JSON.parse($('char-dialogue-json').value),report=dialogueDiagnostics(definition),doc=getDocument(),id=selectedId;if(report.errors.length)throw Error(report.errors.join(' '));let saved=false;await run(()=>{doc.dialogueDefinition(definition,{replace:true});saved=true;},'Dialogue saved. Apply its reference to the character.');if(!saved||getDocument()!==doc||selectedId!==id)return;
  // Scene refresh repopulates the form. Select the new resource after it finishes.
  $('char-dialogue').value=definition.id;$('char-dialogue-status').textContent=report.warnings.join(' ')||'Validated. Set Can talk and Apply character changes to bind this conversation.';}catch(e){$('char-dialogue-status').textContent=e.message;}};
 return {sync};
}
